let bateria = 100
game.onUpdateInterval(1000, function () {
    bateria = bateria - 10
    movil.sayText(bateria)
    if (bateria < 20) {
        movil.sayText("Modo ahorro")
    }
})

// Evento: al chocar con un enemigo
sprites.onOverlap(SpriteKind.Player, SpriteKind.Enemy, function (sprite, otherSprite) {
    info.changeLifeBy(-1)
    otherSprite.destroy()
})
// Bucle: se repite siempre
forever(function () {
    if (info.score() >= 10) {
        game.gameOver(true)
    }
})

sprites.onOverlap(SpriteKind.Player, SpriteKind.Food, function (sprite, moneda) {
    moneda.destroy()
    info.changeScoreBy(1)
})
info.startCountdown(45)
info.onCountdownEnd(function () {
    game.gameOver(info.score() >= 10)
})

let premios = ["Escudo", "Vida extra", "Turbo", "Imán", "x2 puntos"]
controller.A.onEvent(ControllerButtonEvent.Pressed, function () {
    let i = randint(0, premios.length - 1)
    cofre.sayText(premios[i], 1500)
    info.changeScoreBy(1)
})

let licencias = ["CC BY: úsalo citando a su autor/a.", "CC BY-SA: cita y comparte igual.", "CC BY-NC: cita y sin vender.", "CC0: dominio público, sin condiciones."]
let indice = 0
controller.A.onEvent(ControllerButtonEvent.Pressed, function () {
    if (indice < licencias.length) {
        game.showLongText(licencias[indice], DialogLayout.Bottom)
        indice += 1
    } else {
        game.splash("¡Ya conoces las 4 licencias!")
    }
})

let indice = 1                      // bug 1
controller.A.onEvent(ControllerButtonEvent.Pressed, function () {
    if (indice <= licencias.length) { // bug 2
        game.showLongText(licencias[indice], DialogLayout.Bottom)
        indice += 1
    }
})
// bug 3: al volver a jugar, indice no vuelve a 0

game.onUpdateInterval(3000, function () {
    let enemigo = sprites.create(img`...`, SpriteKind.Enemy)
    tiles.placeOnRandomTile(enemigo, assets.tile`suelo`)
    enemigo.follow(jugador, 40)
})

let niveles = [tilemap`nivel1`, tilemap`nivel2`, tilemap`nivel3`]
let nivel = 0
tiles.setCurrentTilemap(niveles[nivel])
scene.onOverlapTile(SpriteKind.Player, assets.tile`meta`, function (sprite, location) {
    nivel += 1
    if (nivel < niveles.length) {
        tiles.setCurrentTilemap(niveles[nivel])
    } else {
        game.gameOver(true)
    }
})
